using Godot;
using System;
using System.Linq;
using System.IO;
using HakutaiKagami.Core.Contracts;
public partial class NewGameRuntime
{
 OptionButton unreadChoice=null!;EntityId[] unreadIds=[];
 void BuildMailUI(Node bar){unreadChoice=new(){CustomMinimumSize=new(145,0),FitToLongestItem=false,TextOverrunBehavior=TextServer.OverrunBehavior.TrimEllipsis,TooltipText="未開封の書状を選びます。差出人と一覧番号だけを表示し、内容は開封するまで表示しません。"};unreadChoice.AddItem("未開封なし");bar.AddChild(unreadChoice);}
 void RefreshMail(){var rows=Branch(Session.PlayerControl).Knowledge.Messages.Where(m=>m.KnownBody==null).ToArray();var next=rows.Select(m=>m.Id).ToArray();EntityId? selected=unreadChoice.Selected>=0&&unreadChoice.Selected<unreadIds.Length?unreadIds[unreadChoice.Selected]:null;if(!next.SequenceEqual(unreadIds)){unreadChoice.Clear();for(int n=0;n<rows.Length;n++){string sender=Snapshot().Definitions.Characters.FirstOrDefault(c=>c.Id.Value==rows[n].Sender)?.Name??"差出人";unreadChoice.AddItem("書状"+(n+1)+"（"+sender+"）");unreadChoice.SetItemTooltip(n,sender+"からの未開封書状。内容は未確認です。");}unreadIds=next;int i=Array.FindIndex(next,id=>id==selected);if(next.Length>0)unreadChoice.Select(Math.Max(0,i));else unreadChoice.AddItem("未開封なし");}unreadChoice.Disabled=rows.Length==0;}
 void OpenSelectedMail(){RefreshMail();if(unreadIds.Length==0){message.Text="未開封の書状はありません。";return;}var opened=unreadIds[unreadChoice.Selected];Submit(Session.Open(Session.PlayerControl,opened,Session.Revision));if(Snapshot().Messaging.Messages.Single(m=>m.Id==opened.Value).Kind==TruceNegotiations.Kind)ShowTruceLetter(opened);else if(Snapshot().Messaging.Messages.Single(m=>m.Id==opened.Value).Kind==PersonalCompanions.ReportKind)ShowCompanionReport(opened);else if(Snapshot().Messaging.Messages.Single(m=>m.Id==opened.Value).Kind==FactionNotices.Kind)ShowFactionLetter(opened);else if(AssessmentNotice.Inbox(Session,Session.PlayerControl).Any(c=>c.Message==opened&&c.Known!=null))ShowWorkAssessment(opened);else if(NewGameWork.Enabled(Snapshot())&&Snapshot().Messaging.Messages.Single(m=>m.Id==opened.Value).Kind=="new-military-notice")ShowMilitaryWork(opened);else if(WorkFollowup.Enabled(Snapshot())&&Snapshot().Messaging.Messages.Single(m=>m.Id==opened.Value).Kind=="service-notice"&&ContractJson.Read<CareerNotice>(System.Text.Encoding.UTF8.GetBytes(Snapshot().Messaging.Messages.Single(m=>m.Id==opened.Value).Body)).Statement is CareerStatement.AwaitingReports or CareerStatement.Ended)ShowServiceDirection(new(Snapshot().Messaging.Messages.Single(m=>m.Id==opened.Value).SenderId));else if(Branch(Session.PlayerControl).Knowledge.Messages.Single(m=>m.Id==opened).KnownBody==KnownWork()?.Id.Value)ShowKnownWork();}
 internal void SelectUnreadMail(EntityId id){Refresh();int i=Array.IndexOf(unreadIds,id);if(i<0)throw new InvalidDataException("本人に届いた未開封書状ではありません");unreadChoice.Select(i);}
}
